try{const saved=migratePatch(JSON.parse(localStorage.getItem('pixel-rave-modular-v3')||localStorage.getItem('pixel-rave-modular-v2')));if(saved)patch=saved;}catch{}
let ctx,engine,running=false,wanted=false,request=0,timer,nextTime=0,step=0,bar=1,queue=[],pendingPort=null,toastTimer,edited=false;
const held=new Map(),knobs=new Map();
const history=createHistory(patch);
let connections,clipboard,keyboardOctave=0;
const toast=message=>{$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);};
function persist(mark=true,group){if(previewEngine)stopPreview();history.record(patch,group);$('#undo').disabled=!history.canUndo;$('#redo').disabled=!history.canRedo;if(mark){edited=true;$('#patch-edited').hidden=false;}try{localStorage.setItem('pixel-rave-modular-v3',JSON.stringify(patch));}catch{}}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function normalized(key,value){const c=controls[key];return c.log?Math.log(value/c.min)/Math.log(c.max/c.min):(value-c.min)/(c.max-c.min);}
function actual(key,n){const c=controls[key],raw=c.log?c.min*(c.max/c.min)**n:c.min+n*(c.max-c.min);return clamp(Math.round(raw/c.step)*c.step,c.min,c.max);}
function format(key,v){const c=controls[key];if(c.unit==='Hz')return v>=1000?(v/1000).toFixed(2)+' kHz':(v<20?v.toFixed(2):Math.round(v))+' Hz';if(c.unit==='s')return v<1?Math.round(v*1000)+' ms':v.toFixed(2)+' s';return (c.step<1?v.toFixed(1):v)+(c.unit==='%'?'%':' '+c.unit);}
function knob(key,module){const c=controls[key];return `<div class="knob" data-control="${key}"><label for="knob-${key}">${c.label}</label><div class="knob-body"><span class="knob-indicator"></span><input id="knob-${key}" type="range" min="0" max="1000" step="1" aria-label="${module} ${c.label}"></div><output for="knob-${key}"></output></div>`;}
const knobRow=(keys,module,cls='')=>`<div class="knob-row ${cls}">${keys.map(k=>knob(k,module)).join('')}</div>`;
function jacks(ids){return `<div class="ports">${ids.map(([id,label])=>`<div class="port-group"><button class="jack" data-port="${id}" data-direction="${ports[id].direction}" data-type="${ports[id].type}" aria-label="${ports[id].label}" title="${ports[id].label}"></button><span class="port-label">${label}</span></div>`).join('')}</div>`;}
function waves(key,options=[['sine','SINE'],['triangle','TRI'],['sawtooth','SAW'],['square','SQR']]){return `<div class="wave-select" data-choice="${key}">${options.map(([value,label])=>`<button data-value="${value}" aria-label="${key} ${label}" aria-pressed="false">${label}</button>`).join('')}</div>`;}
const plot=type=>`<canvas data-plot="${type}" width="300" height="76" aria-label="Visualização ${type}"></canvas>`;
const modules=[
 {id:'oscA',name:'OSCILLATOR A',code:'VCO / 01',color:'#ec9c66',body:plot('oscA')+waves('waveA')+knobRow(['tuneA','detuneA'],'OSC A'),ports:[['oscA.cv','PITCH CV'],['oscA.out','AUDIO OUT']]},
 {id:'oscB',name:'OSCILLATOR B',code:'VCO / 02',color:'#ddb56a',body:plot('oscB')+waves('waveB')+knobRow(['tuneB','detuneB'],'OSC B'),ports:[['oscB.cv','PITCH CV'],['oscB.out','AUDIO OUT']]},
 {id:'mixer',name:'MIXER',code:'SUM / 03',color:'#e4c46a',body:knobRow(['mixA','mixB','sub','noise'],'MIXER','mixer-knobs'),ports:[['mixer.a','IN A'],['mixer.b','IN B'],['mixer.out','OUT']]},
 {id:'filter',name:'FILTER',code:'VCF / 04',color:'#c1d882',body:plot('filter')+waves('filterType',[['lowpass','LOW PASS'],['bandpass','BAND'],['highpass','HIGH PASS']])+knobRow(['cutoff','resonance','envAmount'],'FILTER','compact'),ports:[['filter.in','AUDIO IN'],['filter.cv','CUTOFF CV'],['filter.out','OUT']]},
 {id:'amp',name:'AMPLIFIER',code:'VCA / 05',color:'#7fc8bc',body:'<div class="amp-display"><span>GATE / NOTE</span><strong id="gate-display">IDLE</strong></div>'+knobRow(['amp','glide'],'VCA')+'<p class="module-detail">ENVELOPE → AMPLITUDE</p>',ports:[['vca.in','AUDIO IN'],['vca.cv','GATE CV'],['vca.out','OUT']]},
 {id:'envelope',name:'ENVELOPE',code:'ADSR / 06',color:'#bca1df',body:plot('envelope')+knobRow(['attack','decay','sustain','release'],'ENVELOPE','compact')+'<p class="module-detail">ATTACK · DECAY · SUSTAIN · RELEASE</p>',ports:[['env.out','CV OUT']]},
 {id:'lfo',name:'MODULATION',code:'LFO / 07',color:'#79c5d3',body:plot('lfo')+waves('lfoWave')+knobRow(['lfoRate','lfoDepth'],'LFO'),ports:[['lfo.out','CV OUT']]},
 {id:'drive',name:'SATURATION',code:'DRIVE / 08',color:'#e98b77',body:plot('drive')+knobRow(['drive','tone','driveMix'],'DRIVE','compact')+'<p class="module-detail">SOFT CLIP / 2× OVERSAMPLING</p>',ports:[['drive.in','AUDIO IN'],['drive.out','OUT']]},
 {id:'delay',name:'TAPE ECHO',code:'DELAY / 09',color:'#9eb2e9',body:plot('delay')+knobRow(['delayTime','feedback','delayMix'],'DELAY','compact')+'<p class="module-detail">TEMPO FREE / FEEDBACK LOOP</p>',ports:[['delay.in','AUDIO IN'],['delay.out','OUT']]},
 {id:'output',name:'OUTPUT',code:'MASTER / 10',color:'#b9cc98',body:`<div class="output-top">${knob('master','OUTPUT')}<div class="meter" aria-label="Nível de saída">${'<i></i>'.repeat(10)}</div></div>${plot('scope')}<div class="output-bottom"><span id="meter-text">−∞ dB</span><span>LIMITER · ON</span></div>`,ports:[['output.in','AUDIO IN']]}
];
for(const m of modules){const section=document.createElement('article');section.id='module-'+m.id;section.className='module module-'+m.id;section.style.setProperty('--accent',m.color);section.innerHTML=`<div class="module-header"><h2>${m.name}</h2><span class="module-code">${m.code}</span></div>${m.body}${jacks(m.ports)}`;$('#rack').append(section);}

function updateKnob(key){const host=knobs.get(key),v=patch.params[key],n=normalized(key,v);host.querySelector('input').value=Math.round(n*1000);host.querySelector('input').setAttribute('aria-valuetext',format(key,v));host.querySelector('output').textContent=format(key,v);host.querySelector('.knob-body').style.setProperty('--angle',(n*270-135)+'deg');}
function setParam(key,value){patch.params[key]=value;updateKnob(key);engine?.update(key);drawPlots();persist(true,'param:'+key);}
for(const host of document.querySelectorAll('[data-control]')){const key=host.dataset.control,input=host.querySelector('input'),body=host.querySelector('.knob-body');knobs.set(key,host);input.addEventListener('input',()=>setParam(key,actual(key,Number(input.value)/1000)));let drag;
 body.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();input.focus({preventScroll:true});body.setPointerCapture(e.pointerId);drag={y:e.clientY,n:normalized(key,patch.params[key])};});
 body.addEventListener('pointermove',e=>{if(!drag)return;setParam(key,actual(key,clamp(drag.n+(drag.y-e.clientY)/(e.shiftKey?1000:180),0,1)));});
 const release=()=>drag=undefined;body.addEventListener('pointerup',release);body.addEventListener('pointercancel',release);body.addEventListener('dblclick',()=>setParam(key,createPatch(patch.genre,55,patch.presetId).params[key]));
}
for(const group of document.querySelectorAll('[data-choice]'))for(const button of group.querySelectorAll('button'))button.onclick=()=>{patch.params[group.dataset.choice]=button.dataset.value;updateChoices();engine?.update();drawPlots();persist();};
function updateChoices(){for(const group of document.querySelectorAll('[data-choice]'))for(const b of group.querySelectorAll('button')){const active=patch.params[group.dataset.choice]===b.dataset.value;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);}}

function waveValue(type,x){const phase=x%1;return type==='sine'?Math.sin(phase*Math.PI*2):type==='triangle'?1-4*Math.abs(phase-.5):type==='sawtooth'?2*phase-1:phase<.5?1:-1;}
function drawPlots(){for(const canvas of document.querySelectorAll('[data-plot]')){const type=canvas.dataset.plot;if(type==='scope')continue;const p=canvas.getContext('2d'),w=canvas.width,h=canvas.height,params=patch.params;p.clearRect(0,0,w,h);p.strokeStyle='#344348';p.lineWidth=1;p.beginPath();p.moveTo(0,h/2);p.lineTo(w,h/2);for(let x=0;x<w;x+=30){p.moveTo(x,0);p.lineTo(x,h);}p.stroke();p.strokeStyle=getComputedStyle(canvas.closest('.module')).getPropertyValue('--accent');p.lineWidth=1.7;p.beginPath();
 if(type==='envelope'){const a=.04+params.attack/2*.26,d=.1+params.decay/2*.2,r=.1+params.release/3*.25,sy=h-8-params.sustain/100*(h-16);p.moveTo(0,h-7);p.lineTo(w*a,8);p.lineTo(w*(a+d),sy);p.lineTo(w*(1-r),sy);p.lineTo(w,h-7);}
 else for(let x=0;x<w;x++){let y;if(type==='oscA'||type==='oscB'||type==='lfo')y=h/2-waveValue(params[type==='oscA'?'waveA':type==='oscB'?'waveB':'lfoWave'],x/w*(type==='lfo'?2:3))*h*.32;else if(type==='drive')y=h/2-Math.tanh((x/w*2-1)*(1+params.drive/100*18))*h*.38;else if(type==='filter'){const c=normalized('cutoff',params.cutoff),v=1/(1+Math.exp((x/w-c)*16));y=h-9-(params.filterType==='highpass'?1-v:params.filterType==='bandpass'?Math.exp(-(((x/w-c)*7)**2)):v)*(h-18);}else{const n=Math.floor(x/w*6),phase=x/w*6-n;y=h-9-Math.exp(-phase*12)*Math.pow(params.feedback/100,n)*(h-18);}x?p.lineTo(x,y):p.moveTo(x,y);}p.stroke();}}

connections=setupConnections({getPatch:()=>patch,notify:toast,change:(mutate,group,redraw=true)=>{mutate(patch);if(redraw)engine?.route();else engine?.updateModulation();persist(true,group);if(redraw)connections?.refresh();}});
function cancelConnection(){connections.cancel();}
function drawCables(){connections.draw();}
$('#reset-routing').onclick=()=>{patch.routes=defaultRoutes.map(r=>[...r]);patch.modAmounts={};engine?.route();cancelConnection();connections.refresh();persist();toast('Rotas restauradas. Desfazer recupera o patch anterior.');};

let page=0,previewEngine,previewTimer,previewEnd,previewRequest=0;
const lastNotes=Array(64).fill(41);
function drawSequence(){const host=$('#sequence');host.replaceChildren();patch.sequence.slice(page*16,page*16+16).forEach((note,j)=>{const index=page*16+j;if(note)lastNotes[index]=note;const cell=document.createElement('div');cell.className='step'+(note?' on':'');cell.dataset.index=index;const button=document.createElement('button');button.className='step-toggle';button.setAttribute('aria-label','Ativar passo '+(index+1));button.setAttribute('aria-pressed',note>0);button.innerHTML=String(index+1).padStart(2,'0')+'<i></i>';const select=document.createElement('select');select.setAttribute('aria-label','Nota do passo '+(index+1));for(const n of [0,...Array.from({length:61},(_,i)=>i+24)]){const o=document.createElement('option');o.value=n;o.textContent=noteName(n);select.append(o);}select.value=note;select.onchange=()=>{patch.sequence[index]=Number(select.value);if(patch.sequence[index]){lastNotes[index]=patch.sequence[index];auditionNote(patch.sequence[index]);}cell.classList.toggle('on',!!patch.sequence[index]);button.setAttribute('aria-pressed',!!patch.sequence[index]);persist();};button.onclick=()=>{patch.sequence[index]=patch.sequence[index]?0:lastNotes[index];select.value=patch.sequence[index];if(patch.sequence[index])auditionNote(patch.sequence[index]);cell.classList.toggle('on',!!patch.sequence[index]);button.setAttribute('aria-pressed',!!patch.sequence[index]);persist();};cell.append(button,select);host.append(cell);});}
function drawDrums(){const names=['BUMBO','CAIXA / CLAP','HAT','OPEN HAT','TOM GRAVE','TOM AGUDO','CONGA','SLAP'];const host=$('#drum-grid');host.replaceChildren();patch.drums.forEach((notes,row)=>{const div=document.createElement('div');div.className='drum-row'+(patch.muted?.[row]?' muted':'');const label=document.createElement('div');label.className='drum-label';const audition=document.createElement('button');audition.className='drum-audition';audition.textContent=names[row];audition.setAttribute('aria-label','Ouvir '+names[row]);audition.onclick=()=>auditionDrum(row);const mute=document.createElement('button');mute.className='drum-mute';mute.textContent='M';mute.setAttribute('aria-label','Silenciar '+names[row]);mute.setAttribute('aria-pressed',!!patch.muted?.[row]);mute.onclick=()=>{patch.muted??=Array(8).fill(false);patch.muted[row]=!patch.muted[row];mute.setAttribute('aria-pressed',patch.muted[row]);div.classList.toggle('muted',patch.muted[row]);persist();};label.append(audition,mute);const pads=document.createElement('div');pads.className='drum-pads';notes.slice(page*16,page*16+16).forEach((v,j)=>{const i=page*16+j;const b=document.createElement('button');b.className='drum-pad'+(v?' on':'');b.dataset.step=i;b.style.opacity=v?.35+v*.65:1;b.title=Math.round(v*100)+'%';b.setAttribute('aria-label',names[row]+' passo '+(i+1));b.setAttribute('aria-pressed',!!v);b.onclick=()=>{patch.drums[row][i]=patch.drums[row][i]===0?.45:patch.drums[row][i]<.7?.75:patch.drums[row][i]<1?1:0;b.style.opacity=patch.drums[row][i]?.35+patch.drums[row][i]*.65:1;b.title=Math.round(patch.drums[row][i]*100)+'%';b.classList.toggle('on',!!patch.drums[row][i]);b.setAttribute('aria-pressed',!!patch.drums[row][i]);if(patch.drums[row][i]&&!running&&!wanted)auditionDrum(row,patch.drums[row][i]);persist();};pads.append(b);});div.append(label,pads);host.append(div);});}
function sync(){for(const key of knobs.keys())updateKnob(key);updateChoices();drawPlots();drawSequence();drawDrums();$('#patch-name').textContent=patch.name;$('#vibe').value=patch.genre;$('#tempo').value=patch.bpm;$('#gate').value=patch.gate;$('#gate-value').textContent=patch.gate+'%';$('#swing').value=patch.swing;$('#swing-value').textContent=patch.swing+'%';syncBypasses();connections.refresh();$('#patch-description').textContent=getPreset(patch.presetId).description;syncLibrary();$('#rhythm').setAttribute('aria-pressed',patch.rhythm);$('#rhythm').textContent=patch.rhythm?'● BATERIA LIGADA':'○ BATERIA DESLIGADA';$('#patch-edited').hidden=!edited;requestAnimationFrame(drawCables);}

async function ensureAudio(){if(!ctx)ctx=new AudioContext({latencyHint:'interactive'});if(!engine)engine=new ModularSynth(ctx,patch);await ctx.resume();if(ctx.state!=='running')throw new Error('O áudio está suspenso. Tente Play novamente.');$('#audio-status').textContent='WEB AUDIO · '+Math.round(ctx.sampleRate/1000)+' KHZ';}
function stop(){stopPreview();request++;wanted=false;running=false;clearInterval(timer);timer=undefined;queue=[];step=0;bar=1;held.clear();const previous=engine;engine=undefined;if(previous){previous.panic();setTimeout(()=>previous.dispose(),40);}$('#play').innerHTML='▶ <span>PLAY</span>';$('#play').classList.remove('playing');$('#play').setAttribute('aria-label','Iniciar sequenciador');$('#position').textContent='01.01';$('#gate-display').textContent='IDLE';$('#note-readout').textContent='—';document.querySelectorAll('.current,.pressed').forEach(el=>el.classList.remove('current','pressed'));}
async function play(){stopPreview();if(running||wanted){stop();return;}wanted=true;const token=++request;try{await ensureAudio();if(token!==request)return;engine.enable();running=true;nextTime=ctx.currentTime+.06;step=0;bar=1;clearInterval(timer);timer=setInterval(schedule,25);schedule();$('#play').innerHTML='■ <span>STOP</span>';$('#play').classList.add('playing');$('#play').setAttribute('aria-label','Parar sequenciador');}catch(e){if(token===request){wanted=false;toast(e.message);}}}
function schedule(){if(!running)return;if(nextTime<ctx.currentTime-.1){nextTime=ctx.currentTime+.04;queue=[];}while(nextTime<ctx.currentTime+.11){engine.step(step,nextTime);queue.push({step,time:nextTime,bar,note:patch.sequence[step]});nextTime+=stepDuration(patch,step);step++;if(step===64){step=0;bar++;}}}
function replacePatch(next,resume=false){stop();engine?.dispose();engine=undefined;patch=next;page=0;edited=false;lastNotes.fill(41);cancelConnection();sync();persist(false);if(resume)play();}
$('#vibe').onchange=e=>{const resume=running||wanted;replacePatch(createPatch(e.target.value,patch.params.master),resume);toast(patch.name+' · '+patch.bpm+' BPM');};
$('#play').onclick=play;$('#stop').onclick=stop;
$('#tempo').oninput=e=>{const value=Number(e.target.value);if(value>=60&&value<=200){patch.bpm=value;engine?.update();persist(true,'tempo');}};$('#tempo').onchange=()=>$('#tempo').value=patch.bpm;
$('#gate').oninput=e=>{patch.gate=Number(e.target.value);$('#gate-value').textContent=patch.gate+'%';persist(true,'gate');};
$('#swing').oninput=e=>{patch.swing=Number(e.target.value);$('#swing-value').textContent=patch.swing+'%';persist(true,'swing');};
$('#rhythm').onclick=()=>{patch.rhythm=!patch.rhythm;$('#rhythm').setAttribute('aria-pressed',patch.rhythm);$('#rhythm').textContent=patch.rhythm?'● BATERIA LIGADA':'○ BATERIA DESLIGADA';if(!patch.rhythm)engine?.drums.silence();persist();};
$('#clear-sequence').onclick=()=>{patch.sequence.fill(0);drawSequence();persist();toast('Sequência limpa. Escolha notas nos passos.');};
$('#variation').onclick=()=>{const scale=patch.genre==='dnb'||patch.genre==='funk'?[29,32,36,39,41]:[41,44,48,51,53,56,60,63];patch.sequence=patch.sequence.map(v=>Math.random()<.3?(Math.random()<.25?0:scale[Math.floor(Math.random()*scale.length)]):v);drawSequence();persist();toast('Nova variação da sequência.');};

const computerKeys=['a','w','s','e','d','f','t','g','y','h','u','j','k','o','l','p',';'];
const keyMap=new Map(computerKeys.map((key,i)=>[key,48+i]));
async function noteDown(id,note){stopPreview();if(held.has(id))return;if(running||wanted)stop();held.set(id,note);keyLights();try{await ensureAudio();if([...held.keys()].at(-1)!==id)return;engine.enable();engine.noteOn(note);$('#gate-display').textContent=noteName(note);$('#note-readout').textContent=noteName(note);}catch(e){held.delete(id);keyLights();toast(e.message);}}
function noteUp(id){if(!held.has(id))return;held.delete(id);const note=[...held.values()].at(-1);if(note!==undefined){engine?.noteOn(note);$('#gate-display').textContent=noteName(note);$('#note-readout').textContent=noteName(note);}else{engine?.noteOff();$('#gate-display').textContent='RELEASE';$('#note-readout').textContent='—';}keyLights();}
function keyLights(note){document.querySelectorAll('.key').forEach(k=>k.classList.toggle('pressed',[...held.values()].includes(Number(k.dataset.note)+keyboardOctave*12)||Number(k.dataset.note)+keyboardOctave*12===note));}
let whites=0;for(let n=48;n<=72;n++){const black=[1,3,6,8,10].includes(n%12),key=document.createElement('button');key.className='key'+(black?' black':'');key.dataset.note=n;key.setAttribute('aria-label','Tocar '+noteName(n));key.textContent=computerKeys[n-48]?.toUpperCase()||noteName(n);if(black)key.style.left=(whites/15*100-2.05)+'%';else whites++;key.onpointerdown=e=>{e.preventDefault();key.setPointerCapture(e.pointerId);noteDown('pointer'+e.pointerId,n+keyboardOctave*12);};key.onpointerup=e=>noteUp('pointer'+e.pointerId);key.onpointercancel=e=>noteUp('pointer'+e.pointerId);key.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();noteDown('button'+n,n+keyboardOctave*12);}};key.onkeyup=e=>{if(['Enter',' '].includes(e.key))noteUp('button'+n);};$('#keyboard').append(key);}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#value-dialog').open||$('#help-dialog').open)return;cancelConnection();stop();return;}if(!$('#help-dialog').open&&!$('#value-dialog').open&&(e.ctrlKey||e.metaKey)&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)&&['z','y'].includes(e.key.toLowerCase())){e.preventDefault();restoreHistory(e.key.toLowerCase()==='y'||e.shiftKey?'redo':'undo');return;}if($('#help-dialog').open||$('#value-dialog').open||['INPUT','SELECT','TEXTAREA','BUTTON'].includes(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Space'){e.preventDefault();if(!e.repeat)play();return;}const note=keyMap.get(e.key.toLowerCase());if(note!==undefined&&!e.repeat){e.preventDefault();noteDown('key'+e.code,note+keyboardOctave*12);}});
document.addEventListener('keyup',e=>noteUp('key'+e.code));window.addEventListener('blur',()=>{if(held.size)stop();});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});

const samples=new Uint8Array(2048),spectrum=new Uint8Array(1024);let lastFrame=0;
function animate(now){requestAnimationFrame(animate);if(now-lastFrame<33)return;lastFrame=now;
 if(running&&ctx){let event;while(queue.length&&queue[0].time<=ctx.currentTime)event=queue.shift();if(event){if($('#follow-bars').checked&&page!==Math.floor(event.step/16)){page=Math.floor(event.step/16);drawSequence();drawDrums();drawPages();}document.querySelectorAll('.step.current,.drum-pad.current').forEach(e=>e.classList.remove('current'));document.querySelectorAll('.drum-pad[data-step="'+event.step+'"]').forEach(e=>e.classList.add('current'));$(`.step[data-index="${event.step}"]`)?.classList.add('current');$('#position').textContent=String(Math.floor(event.step/16)+1).padStart(2,'0')+'.'+String(event.step%16+1).padStart(2,'0');$('#gate-display').textContent=event.note?noteName(event.note):'REST';$('#note-readout').textContent=noteName(event.note);keyLights(event.note);}}
 const monitor=previewEngine||engine;const canvas=$('[data-plot="scope"]'),p=canvas.getContext('2d'),w=canvas.width,h=canvas.height;p.clearRect(0,0,w,h);p.strokeStyle='#334741';p.lineWidth=1;p.beginPath();p.moveTo(0,h/2);p.lineTo(w,h/2);p.stroke();p.strokeStyle='#b9cc98';p.lineWidth=1.5;p.beginPath();let power=0;
 if(monitor){monitor.analyser.getByteTimeDomainData(samples);monitor.analyser.getByteFrequencyData(spectrum);for(let i=0;i<samples.length;i++){const v=(samples[i]-128)/128;power+=v*v;const x=i/samples.length*w,y=h/2-v*h*.45;i?p.lineTo(x,y):p.moveTo(x,y);}}else{p.moveTo(0,h/2);p.lineTo(w,h/2);}p.stroke();const rms=Math.sqrt(power/samples.length);$('#meter-text').textContent=rms>.0001?(20*Math.log10(rms)).toFixed(1)+' dB':'−∞ dB';document.querySelectorAll('.meter i').forEach((el,i)=>{const v=monitor?spectrum[Math.floor(2**(i*.8+1))]/255:0;el.style.height=(4+v*48)+'px';el.style.opacity=.2+v*.8;});
}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('#save').onclick=()=>{download(new Blob([JSON.stringify(patch,null,2)],{type:'application/json'}),'pixel-rave-modular-'+patch.presetId+'.json');toast('Patch salvo com parâmetros, cabos e sequência.');};
$('#load').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>150000)throw new Error('Arquivo muito grande.');const next=migratePatch(JSON.parse(await file.text()));if(!next)throw new Error('Abra um patch JSON do sintetizador modular (v2 ou v3).');replacePatch(next);toast('Patch restaurado.');}catch(err){toast(err.message);}e.target.value='';};
$('#wav').onclick=async()=>{const b=$('#wav');b.disabled=true;b.textContent='RENDERIZANDO…';try{const blob=await exportWav(structuredClone(patch));download(blob,'pixel-rave-modular-'+patch.presetId+'-'+patch.bpm+'bpm.wav');toast('WAV pronto: quatro compassos + cauda dos efeitos.');}catch(e){toast('Falha ao exportar: '+e.message);}finally{b.disabled=false;b.textContent='EXPORTAR WAV ↗';}};
$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();
for(const host of [$('#sequence'),$('#drum-grid')]){host.addEventListener('pointerdown',()=>$('#follow-bars').checked=false);host.addEventListener('focusin',()=>$('#follow-bars').checked=false);}
function drawPages(){document.querySelectorAll('[data-bar]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.bar)===page));}
function syncLibrary(){const select=$('#preset');select.replaceChildren();for(const item of presetLibrary[patch.genre]){const option=document.createElement('option');option.value=item.id;option.textContent=item.name;select.append(option);}select.value=patch.presetId;candidateDescription();drawPages();}
function candidateDescription(){const p=getPreset($('#preset').value);$('#preset-info').textContent=p.bpm+' BPM · '+p.description;}
function stopPreview(){previewRequest++;clearInterval(previewTimer);clearTimeout(previewEnd);previewEngine?.dispose();previewEngine=undefined;$('#preview').textContent='▶ OUVIR';}
$('#preset').onchange=()=>{stopPreview();candidateDescription();};
$('#load-preset').onclick=()=>{const resume=running||wanted;replacePatch(createPatch(patch.genre,patch.params.master,$('#preset').value),resume);toast('Preset carregado.');};
$('#preview').onclick=async()=>{if(previewEngine){stopPreview();return;}stop();const token=previewRequest;try{await ensureAudio();if(token!==previewRequest)return;const candidate=createPatch(patch.genre,patch.params.master,$('#preset').value);previewEngine=new ModularSynth(ctx,candidate);previewEngine.enable();let index=0,time=ctx.currentTime+.05;$('#preview').textContent='■ PARAR PRÉVIA';const tick=()=>{while(previewEngine&&index<64&&time<ctx.currentTime+.12){previewEngine.step(index,time);time+=stepDuration(candidate,index++);}if(index===64){clearInterval(previewTimer);previewEnd=setTimeout(stopPreview,Math.max(0,(time-ctx.currentTime+1)*1000));}};previewTimer=setInterval(tick,25);tick();}catch(e){stopPreview();toast(e.message);}};
for(const b of document.querySelectorAll('[data-bar]'))b.onclick=()=>{page=Number(b.dataset.bar);$('#follow-bars').checked=false;drawSequence();drawDrums();drawPages();};
function restoreHistory(direction){const next=history[direction]();if(!next)return;const resume=running;const oldPage=page;replacePatch(next,resume);page=oldPage;edited=true;$('#patch-edited').hidden=false;drawSequence();drawDrums();drawPages();toast(direction==='undo'?'Edição desfeita.':'Edição refeita.');}
$('#undo').onclick=()=>restoreHistory('undo');$('#redo').onclick=()=>restoreHistory('redo');
function editBar(next){$('#follow-bars').checked=false;Object.assign(patch,next);drawSequence();drawDrums();drawPages();persist();}
$('#copy-bar').onclick=()=>{$('#follow-bars').checked=false;clipboard=copyBar(patch,page);$('#paste-bar').disabled=false;toast('Compasso '+(page+1)+' copiado com notas e bateria.');};
$('#paste-bar').onclick=()=>{if(clipboard)editBar(pasteBar(patch,page,clipboard));};
$('#duplicate-bar').onclick=()=>{const phrase=copyBar(patch,page);page=(page+1)%4;$('#follow-bars').checked=false;editBar(pasteBar(patch,page,phrase));toast('Copiado para o compasso '+(page+1)+'.');};
for(const b of document.querySelectorAll('[data-transform]'))b.onclick=()=>editBar(transformBar(patch,page,b.dataset.transform));
async function auditionNote(note){if(running||wanted)return;stopPreview();const token=request;try{await ensureAudio();if(token!==request||!engine||running||wanted)return;engine.enable();engine.noteOn(note,ctx.currentTime,.16);}catch(e){toast(e.message);}}
async function auditionDrum(row,velocity=.8){stopPreview();const token=request;try{await ensureAudio();if(token!==request||!engine)return;engine.enable();engine.drums.trigger(drumTracks[row],velocity,ctx.currentTime+.01);}catch(e){toast(e.message);}}
for(const [id,label]of [['filter','FILTRO'],['drive','DRIVE'],['delay','DELAY']]){const b=document.createElement('button');b.className='module-bypass';b.dataset.bypass=id;b.setAttribute('aria-label','Bypass '+label);b.onclick=()=>{patch.bypass??={};patch.bypass[id]=!patch.bypass[id];engine?.update();syncBypasses();persist();};$('#module-'+id+' .module-header').append(b);}
function syncBypasses(){for(const b of document.querySelectorAll('[data-bypass]')){const off=!!patch.bypass?.[b.dataset.bypass];b.textContent=off?'BYPASS':'ON';b.setAttribute('aria-pressed',off);b.closest('.module').classList.toggle('bypassed',off);}}
let valueKey;
for(const [key,host]of knobs){const output=host.querySelector('output');output.tabIndex=0;output.setAttribute('role','button');output.setAttribute('aria-label','Editar valor exato '+controls[key].label);const open=()=>{valueKey=key;const c=controls[key],input=$('#exact-value');$('#value-title').textContent=c.label;$('#value-label').textContent=c.min+' a '+c.max+' '+c.unit;input.min=c.min;input.max=c.max;input.step=c.step;input.value=patch.params[key];$('#value-error').textContent='';$('#value-dialog').showModal();input.focus();input.select();};output.onclick=open;output.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}};}
$('#value-form').onsubmit=e=>{e.preventDefault();const c=controls[valueKey],v=Number($('#exact-value').value);if(!Number.isFinite(v)||v<c.min||v>c.max){$('#value-error').textContent='Escolha um valor dentro do intervalo.';return;}setParam(valueKey,Math.round(v/c.step)*c.step);$('#value-dialog').close();};
$('#reset-value').onclick=()=>{setParam(valueKey,createPatch(patch.genre,55,patch.presetId).params[valueKey]);$('#value-dialog').close();};$('#cancel-value').onclick=()=>$('#value-dialog').close();
function octave(delta){keyboardOctave=clamp(keyboardOctave+delta,-2,1);const hadHeld=held.size>0;held.clear();if(hadHeld)engine?.noteOff();keyLights();$('#octave-value').textContent=noteName(48+keyboardOctave*12)+'–'+noteName(72+keyboardOctave*12);$('#keyboard-range').textContent=$('#octave-value').textContent;$('#octave-down').disabled=keyboardOctave===-2;$('#octave-up').disabled=keyboardOctave===1;for(const key of document.querySelectorAll('.key')){const note=Number(key.dataset.note)+keyboardOctave*12;key.setAttribute('aria-label','Tocar '+noteName(note));if(!computerKeys[Number(key.dataset.note)-48])key.textContent=noteName(note);}}
$('#octave-down').onclick=()=>octave(-1);$('#octave-up').onclick=()=>octave(1);
$('#module-jump').onchange=e=>document.getElementById(e.target.value)?.scrollIntoView({behavior:'smooth',block:'start'});
sync();requestAnimationFrame(animate);
